import React from 'react';

function Order({ toggleCart }) {
    return (
      <div className="cart-overlay">
        <div className="cart">
          <button className="close-cart" onClick={toggleCart}>Закрыть</button>
          <h1>Корзина</h1>
          <p>Здесь будут отображаться товары, добавленные в корзину.</p>
        </div>
      </div>
    );
  }

export default Order;
